// The flow goes in from the controller once this component's stylesheet is on
// the page (the cards are measured in it), so the canvas mounts empty.
const NO_NODES: never[] = [];
const INTERACTION = { portVisibility: 'always' };
const FLOW_STYLE = { display: 'block', height: '100%', width: '100%' };

export default function ChatbotFlowDemo() {
  const ctl = useRef<ChatbotFlowController | null>(null);
  if (!ctl.current) ctl.current = new ChatbotFlowController();
  const c = ctl.current;
  const [, bump] = useReducer((x: number) => x + 1, 0);
  c.bump = bump;
  const stage = useRef<HTMLDivElement>(null);
  useEffect(() => () => c.destroy(), [c]);

  const onInit = (instance: DiagramInstance) => {
    c.init(instance, stage.current!);
    markReady();
  };

