              {c.chat.map((it) => it.kind === 'typing' ? (
                <div className="pv-typing" key={it.id}><i></i><i></i><i></i></div>
              ) : it.kind === 'btns' ? (
                <div className="pv-btns" key={it.id}>
                  {it.buttons!.map((b, i) => (
                    <button type="button" key={i} className={b.chosen ? 'chosen' : undefined} onClick={() => void c.tap(it.id, i)}>{b.label}</button>
